import itertools, random

def brute_nums(y, n, block):
    k = (n + block - 1)//block
    nums = []
    for idxs in itertools.product(range(n), repeat=k):
        s = 0
        pos = 0
        for st in idxs:
            for j in range(block):
                if pos >= n: break
                s += y[(st+j)%n]; pos += 1
            if pos >= n: break
        nums.append(s)
    nums.sort()
    return nums, k

