from urban_micro.uhi import _block_bootstrap_interval

def fast_nums(y, n, block):
    # reuse helper but recover numerator multiset? Instead compare via interval endpoints
    # Build multiset via composition aggregation independently in ints:
    k = (n + block - 1)//block
    import math
    full = k-1
    bvals = [sum(y[(st+j)%n] for j in range(block)) for st in range(n)]
    out=[]
    counts=[0]*n
    ff=math.factorial(full)
    def emit(last, fn, mult):
        num=fn + sum(y[(last+j)%n] for j in range(n-full*block))
        out.extend([num]*mult)
    def rec(idx, rem):
        if idx==n-1:
            counts[idx]=rem
            fn=sum(c*bvals[j] for j,c in enumerate(counts))
            mult=ff
            for c in counts: mult//=math.factorial(c)
            for ls in range(n): emit(ls, fn, mult)
            return
        for cj in range(rem+1):
            counts[idx]=cj; rec(idx+1, rem-cj)
    if full: rec(0, full)
    else:
        for ls in range(n): emit(ls,0,1)
    out.sort()
    return out, k

